beforeAll(async () => {
  upstream = createServer((req, res) => {
    if (req.url === '/fast') {
      res.writeHead(200, { 'content-type': 'text/plain' });
      res.end('quick');
      return;
    }
    if (req.url === '/slow-headers') {
      // Headers arrive AFTER the proxy's limit: this is the #237 repro shape
      // (an API endpoint thinking for longer than the timeout).
      setTimeout(() => {
        res.writeHead(200, { 'content-type': 'text/plain' });
        res.end('finally');
      }, TIMEOUT_MS + 700);
      return;
    }
    if (req.url === '/stream') {
      // Headers immediately, then a body that takes ~3x the limit to finish.
      // Under the old whole-fetch AbortSignal.timeout this died mid-stream.
      res.writeHead(200, { 'content-type': 'text/plain' });
      res.write('start;');
      let chunks = 0;
      const timer = setInterval(() => {
        chunks++;
        res.write(`chunk${chunks};`);
        if (chunks >= 4) {
          clearInterval(timer);
          res.end('done');
        }
      }, TIMEOUT_MS * 0.75);
      return;
    }
    res.writeHead(404).end();
  });
  await new Promise<void>((resolve) => upstream.listen(0, '127.0.0.1', resolve));
  const address = upstream.address();
  if (typeof address === 'object' && address) upstreamPort = address.port;

  await writeWebviews(getDataDir(), [
    {
      id: WEBVIEW_ID,
      name: 'timeout-under-test',
      url: `http://127.0.0.1:${upstreamPort}/`,
      embedMode: 'proxy',
      trusted: false,
      createdAt: Date.now(),
    },
  ]);
  capability = webviewCapabilities.mint(WEBVIEW_ID, undefined);

  app = Fastify({ logger: false });
  registerWebviewRoutes(app, eventPortStub);
  await app.ready();
})

afterAll(async () => {
  await app.close();
  webviewCapabilities.revokeWebview(WEBVIEW_ID);
  await new Promise<void>((resolve) => upstream.close(() => resolve()));
})

beforeAll(async () => {
  if (!CODEX_AVAILABLE) return;
  codexHome = mkdtempSync(resolve(ROOT, 'tmp', 'codexlab-'));
  trustedWorkdir = mkdtempSync(resolve(ROOT, 'tmp', 'codexlab-work-'));
  untrustedWorkdir = mkdtempSync(resolve(ROOT, 'tmp', 'codexlab-untrusted-'));
  mkdirSync(codexHome, { recursive: true });
  writeFileSync(resolve(codexHome, 'auth.json'), JSON.stringify({ OPENAI_API_KEY: 'sk-test-123' }));
  writeFileSync(resolve(codexHome, 'config.toml'), `[projects."${trustedWorkdir}"]\ntrust_level = "trusted"\n`);

  // Child env: strip the vitest markers so the lab server runs REAL tmux/codex
  const env: Record<string, string | undefined> = { ...process.env };
  delete env.VITEST;
  delete env.VITEST_MODE;
  delete env.VITEST_POOL_ID;
  delete env.VITEST_WORKER_ID;
  delete env.NODE_ENV;
  env.CODEMAN_INSTANCE = INSTANCE;
  env.PATH = `${CODEX_BIN_DIR}:${env.PATH}`;

  server = spawn('npx', ['tsx', 'src/index.ts', 'web', '--port', String(PORT)], {
    cwd: ROOT,
    env: env as NodeJS.ProcessEnv,
    stdio: 'ignore',
    detached: false,
  });

  // Wait for the lab server
  const deadline = Date.now() + 30000;
  for (;;) {
    try {
      const res = await fetch(`${BASE_URL}/api/status`);
      if (res.ok) break;
    } catch {
      /* not up yet */
    }
    if (Date.now() > deadline) throw new Error('lab server did not start on :3222');
    await new Promise((r) => setTimeout(r, 300));
  }

  browser = await chromium.launch({ headless: true });
  context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  page = await context.newPage();
  await page.addInitScript(() => {
    localStorage.setItem('codeman-app-settings', JSON.stringify({ localEchoEnabled: true }));
  });
  await page.goto(BASE_URL, { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => document.body.classList.contains('app-loaded'), { timeout: 10000 });

  sessionId = await createCodexSession(trustedWorkdir);
  await openInBrowser(sessionId);
}, 120_000)

afterAll(async () => {
  for (const id of createdSessions) {
    try {
      await api('DELETE', `/api/sessions/${id}`);
    } catch {
      /* best effort */
    }
  }
  await context?.close();
  await browser?.close();
  server?.kill('SIGTERM');
  try {
    execSync(`${TMUX} kill-server`, { stdio: 'ignore' });
  } catch {
    /* already gone */
  }
}, 30_000)

