    };
    process.env.OTEL_EXPORTER_OTLP_ENDPOINT = collector.url;
    process.env.OTEL_SERVICE_NAME = "bitterbot-otel-e2e";

    // Reset the module-scoped state so the SDK actually re-initializes.
