beforeEach(async () => {
		ctx = await setupForDialect(dialect);

		// Create a posts collection with title and attachment fields
		const registry = new SchemaRegistry(ctx.db);
		await registry.createCollection({
			slug: "posts",
			label: "Posts",
			labelSingular: "Post",
		});
		await registry.createField("posts", {
			slug: "title",
			label: "Title",
			type: "string",
		});

		// Look up the collection id
		const collection = await ctx.db
			.selectFrom("_emdash_collections")
			.select("id")
			.where("slug", "=", "posts")
			.executeTakeFirstOrThrow();

		// Add a `file` field to posts that allows only PDFs
		await ctx.db
			.insertInto("_emdash_fields")
			.values({
				id: ulid(),
				collection_id: collection.id,
				slug: "attachment",
				label: "Attachment",
				type: "file",
				column_type: "TEXT",
				required: 0,
				unique: 0,
				default_value: null,
				validation: JSON.stringify({ allowedMimeTypes: ["application/pdf"] }),
				widget: "file",
				options: null,
				sort_order: 10,
			})
			.execute();

		// Add the column to ec_posts
		await ctx.db.schema.alterTable("ec_posts").addColumn("attachment", "text").execute();

		// Seed two media items
		pdfMediaId = ulid();
		zipMediaId = ulid();
		await ctx.db
			.insertInto("media")
			.values([
				{
					id: pdfMediaId,
					filename: "doc.pdf",
					mime_type: "application/pdf",
					size: 100,
					width: null,
					height: null,
					alt: null,
					caption: null,
					storage_key: "doc.pdf",
					content_hash: null,
					blurhash: null,
					dominant_color: null,
					status: "ready",
					author_id: null,
				},
				{
					id: zipMediaId,
					filename: "x.zip",
					mime_type: "application/zip",
					size: 100,
					width: null,
					height: null,
					alt: null,
					caption: null,
					storage_key: "x.zip",
					content_hash: null,
					blurhash: null,
					dominant_color: null,
					status: "ready",
					author_id: null,
				},
			])
			.execute();
	})

