beforeEach(() => {
  // Reset the process-singleton BEFORE each test (not just after) so the first
  // `new Queue(..., { dataPath })` here actually pins the manager to OUR dataPath.
  // In the full suite a prior file may have left the singleton pinned elsewhere,
  // which would otherwise send our jobs to the wrong DB and make the on-disk
  // assertions read an empty file (flaky failure depending on file order).
  try {
    shutdownManager();
  } catch {
    /* nothing to reset */
  }
})

afterEach(() => {
  // Ensure the singleton is reset even if a test bailed before shutting down.
  try {
    shutdownManager();
  } catch {
    /* already shut down */
  }
  for (const p of createdPaths) {
    for (const suffix of ['', '-wal', '-shm', '-journal']) {
      const f = p + suffix;
      if (existsSync(f)) {
        try {
          rmSync(f, { force: true });
        } catch {
          /* best effort */
        }
      }
    }
  }
  createdPaths.clear();
})

afterEach(async () => {
  while (activeServers.length) {
    const s = activeServers.pop();
    try {
      s?.stop(true);
    } catch {
      /* already stopped */
    }
  }
  // Let force-closed sockets fire their client-side close/error handlers and any
  // residual command timeouts drain before the next test, so a stuck half-open
  // client from one test cannot perturb the timing of the next one.
  await Bun.sleep(150);
})

