    }
    harness = null;
  }
})

afterEach(async () => {
  if (harness) {
    for (const c of harness.clients) {
      try {
        c.close();
      } catch {
        /* ignore */
      }
    }
    for (const f of harness.framed) {
      try {
        f.end();
      } catch {
        /* ignore */
      }
    }
    try {
      harness.server.stop();
    } catch {
      /* ignore */
    }
    try {
      harness.qm.shutdown();
    } catch {
      /* ignore */
    }
    harness = null;
  }
  await Bun.sleep(120);
})

afterEach(() => {
  if (harness) {
    try {
      harness.server.stop();
    } catch {
      /* ignore */
    }
    try {
      harness.qm.shutdown();
    } catch {
      /* ignore */
    }
    harness = null;
  }
})

afterEach(async () => {
  if (activeClient) {
    try {
      activeClient.close();
    } catch {
      /* ignore */
    }
    activeClient = null;
  }
  if (active) {
    try {
      active.proc.kill(9);
      await active.proc.exited;
    } catch {
      /* ignore */
    }
    cleanDb(active.db);
    active = null;
  }
})

afterAll(async () => {
  if (active) {
    try {
      active.proc.kill(9);
      await active.proc.exited;
    } catch {
      /* ignore */
    }
    cleanDb(active.db);
    active = null;
  }
})

afterEach(() => {
  // ALWAYS restore the real clock first — a leaked fake clock would poison
  // every later test file in the run.
  setSystemTime();
  for (const m of openManagers.splice(0)) {
    try {
      m.shutdown();
    } catch {
      /* ignore */
    }
  }
  for (const db of dbPaths.splice(0)) cleanDb(db);
})

afterAll(async () => {
  try {
    await stopServer();
    cleanVolume();
  } finally {
    detachRamDisk();
  }
}, 30000)

afterAll(async () => {
  for (const c of clients) {
    try {
      c.close();
    } catch {
      /* ignore */
    }
  }
  clients.length = 0;
  if (server) {
    try {
      server.proc.kill(9);
      await server.proc.exited;
    } catch {
      /* ignore */
    }
    cleanDb(server.db);
    server = null;
  }
})

