      // Anchor: 10 eligible orders; store total 100.
      await db.query(
        `INSERT INTO product_stat (product_id, order_count) VALUES ($1, 10)
         ON CONFLICT (product_id) DO UPDATE SET order_count = 10`,
        [anchor]
