beforeAll(async () => {
      // Start webhook receiver
      receivedRequests = [];
      webhookServer = http.createServer((req, res) => {
        let body = "";
        req.on("data", (chunk) => {
          body += chunk;
        });
        req.on("end", () => {
          receivedRequests.push({ headers: req.headers, body });
          res.writeHead(200);
          res.end("OK");
        });
      });
      await new Promise<void>((resolve) =>
        webhookServer.listen(WEBHOOK_PORT, resolve),
      );

      // Start Gmail emulator
      emulator = await createEmulator({
        service: "google",
        port: EMULATOR_PORT,
        seed: {
          google: {
            users: [{ email: TEST_EMAIL, name: "Webhook Test User" }],
            oauth_clients: [
              {
                client_id: "test-client.apps.googleusercontent.com",
                client_secret: "test-secret",
                redirect_uris: ["http://localhost:3000/callback"],
              },
            ],
            messages: SEED_MESSAGES,
          },
        },
      });

      const oauth2Client = new auth.OAuth2(
        "test-client.apps.googleusercontent.com",
        "test-secret",
      );
      oauth2Client.setCredentials({ access_token: "emulator-token" });

      gmailClient = gmail({
        version: "v1",
        auth: oauth2Client,
        rootUrl: emulator.url,
      });

      const logger = createScopedLogger("test");
      provider = new GmailProvider(gmailClient, logger, "test-account-id");

      // Resolve thread ID
      const msg = await gmailClient.users.messages.get({
        userId: "me",
        id: "msg_webhook",
      });
      threadId = msg.data.threadId!;
    })

afterAll(async () => {
      await new Promise<void>((resolve) =>
        webhookServer?.close(() => resolve()),
      );
      await emulator?.close();
    })

beforeAll(async () => {
      emulator = await createEmulator({
        service: "google",
        port: TEST_PORT,
        seed: {
          google: {
            users: [{ email: TEST_EMAIL, name: "Webhook Flow Test" }],
            oauth_clients: [
              {
                client_id: "test-client.apps.googleusercontent.com",
                client_secret: "test-secret",
                redirect_uris: ["http://localhost:3000/callback"],
              },
            ],
            messages: SEED_MESSAGES,
          },
        },
      });

      const oauth2Client = new auth.OAuth2(
        "test-client.apps.googleusercontent.com",
        "test-secret",
      );
      oauth2Client.setCredentials({ access_token: "emulator-token" });

      gmailClient = gmail({
        version: "v1",
        auth: oauth2Client,
        rootUrl: emulator.url,
      });

      provider = new GmailProvider(gmailClient, logger, "test-account-id");

      // Resolve thread IDs in parallel
      const entries = await Promise.all(
        SEED_MESSAGES.map(async (seed) => {
          const msg = await gmailClient.users.messages.get({
            userId: "me",
            id: seed.id,
          });
          return [seed.id, msg.data.threadId!] as const;
        }),
      );
      threadIds = Object.fromEntries(entries);
    })

