      `
      const exitCode = process.env.MOCK_CLI_EXIT_CODE || '0';
      const output = process.env.MOCK_CLI_OUTPUT || 'Mock upload output';
      console.log(output);
      process.exit(parseInt(exitCode));
      `,
    );
  })

