beforeAll(async () => {
  engine = new PGLiteEngine();
  await engine.connect({});
  await engine.initSchema();

  // Seed pages. The Alice prefix has exactly 3 candidates (the case we
  // want both shapes to actually evaluate); the rest are random fillers
  // that contribute to the OLD shape's O(N) aggregation cost.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const db = (engine as any).db;

  // Insert 3 target pages (people/alice-*).
  for (const slug of ['people/alice-example', 'people/alice-research', 'people/alice-engineer']) {
    await engine.putPage(slug, {
      type: 'person',
      title: slug.split('/').pop()!,
      compiled_truth: `# ${slug}`,
      frontmatter: { type: 'person', title: slug, slug },
    }, { sourceId: 'default' });
  }

  // Bulk-insert filler pages. Use a single executeRaw with generate_series
  // for speed; PGLite handles this fine.
  await db.query(
    `INSERT INTO pages (slug, type, title, compiled_truth, frontmatter, source_id, created_at, updated_at)
     SELECT 'filler/page-' || gs::text,
            'note',
            'Filler ' || gs::text,
            '# Filler',
            '{}',
            'default',
            NOW(),
            NOW()
     FROM generate_series(1, ${PAGES}) gs`,
  );

  // Capture id range for link + chunk inserts.
  const fillerIds = await db.query(`SELECT id FROM pages WHERE slug LIKE 'filler/%' LIMIT ${PAGES}`);
  const aliceIds = await db.query(`SELECT id FROM pages WHERE slug LIKE 'people/alice-%'`);
  const allIds = [...fillerIds.rows.map((r: { id: string }) => r.id), ...aliceIds.rows.map((r: { id: string }) => r.id)];

  // Spread LINKS across filler pages (filler→filler). The OLD shape will
  // aggregate ALL of these on every prefix-expansion call; the NEW shape
  // touches only the alice rows via index.
  const linkBatch = 5_000;
  for (let i = 0; i < LINKS; i += linkBatch) {
    const tuples: string[] = [];
    const params: string[] = [];
    let p = 1;
    for (let j = 0; j < linkBatch && i + j < LINKS; j++) {
      const from = allIds[Math.floor(Math.random() * allIds.length)];
      const to = allIds[Math.floor(Math.random() * allIds.length)];
      if (from === to) continue;
      tuples.push(`($${p++}, $${p++}, 'mentions')`);
      params.push(from, to);
    }
    if (tuples.length === 0) continue;
    // ON CONFLICT DO NOTHING — the links table has a unique index across
    // (from, to, type, source, origin); random pairs occasionally collide.
    // Test seeding doesn't care if a few inserts are skipped; the order of
    // magnitude is what matters for the perf comparison.
    await db.query(
      `INSERT INTO links (from_page_id, to_page_id, link_type) VALUES ${tuples.join(',')}
       ON CONFLICT DO NOTHING`,
      params,
    );
  }

  // Spread CHUNKS across all pages. Use a per-page counter so each
  // (page_id, chunk_index) pair is unique — there's a unique index on
  // content_chunks(page_id, chunk_index) so random chunk_index values
  // would collide.
  const chunkCounts = new Map<string, number>();
  const chunkBatch = 5_000;
  for (let i = 0; i < CHUNKS; i += chunkBatch) {
    const tuples: string[] = [];
    const params: (string | number)[] = [];
    let p = 1;
    for (let j = 0; j < chunkBatch && i + j < CHUNKS; j++) {
      const pid = allIds[Math.floor(Math.random() * allIds.length)];
      const idx = chunkCounts.get(pid) ?? 0;
      chunkCounts.set(pid, idx + 1);
      tuples.push(`($${p++}, $${p++}, $${p++})`);
      params.push(pid, idx, `chunk ${i + j}`);
    }
    await db.query(
      `INSERT INTO content_chunks (page_id, chunk_index, chunk_text) VALUES ${tuples.join(',')}`,
      params,
    );
  }
}, 60_000)

beforeAll(async () => {
  engine = new PGLiteEngine();
  await engine.connect({ database_url: '' });
  await engine.initSchema();

  // Seed test pages. Naming pattern:
  //   - alice-example: single-match case (only people/alice-*)
  //   - bob-example vs bob-rosenstein: multi-match tiebreaker (bob-example wins on connections)
  //   - charlie-example vs charlie-bankcroft: multi-match tiebreaker (charlie-example wins on connections)
  //   - dave-example: single-match case
  const pages = [
    { slug: 'people/alice-example', title: 'Alice Example', type: 'person' },
    { slug: 'people/bob-example', title: 'Bob Example', type: 'person' },
    { slug: 'people/bob-rosenstein', title: 'Bob Rosenstein', type: 'person' },
    { slug: 'people/charlie-example', title: 'Charlie Example', type: 'person' },
    { slug: 'people/charlie-bankcroft', title: 'Charlie Bankcroft', type: 'person' },
    { slug: 'people/dave-example', title: 'Dave Example', type: 'person' },
    { slug: 'companies/stripe', title: 'Stripe', type: 'company' },
    { slug: 'companies/stripe-atlas', title: 'Stripe Atlas', type: 'company' },
  ];

  for (const p of pages) {
    await engine.putPage(p.slug, {
      type: p.type as any,
      title: p.title,
      compiled_truth: `# ${p.title}`,
      frontmatter: { type: p.type, title: p.title, slug: p.slug },
    }, { sourceId: 'default' });
  }

  // Give alice-example 10 chunks (single match, ensures it's the resolved target)
  const alicePage = await engine.executeRaw<{ id: string }>(
    `SELECT id FROM pages WHERE slug = 'people/alice-example' AND source_id = 'default'`,
    [],
  );
  if (alicePage.length > 0) {
    for (let i = 0; i < 10; i++) {
      await engine.executeRaw(
        `INSERT INTO content_chunks (page_id, chunk_index, chunk_text)
         VALUES ($1, $2, $3)`,
        [alicePage[0].id, i, `Chunk ${i} about Alice Example`],
      );
    }
  }

  // Give charlie-example more connections than charlie-bankcroft (20 vs 0)
  const charliePage = await engine.executeRaw<{ id: string }>(
    `SELECT id FROM pages WHERE slug = 'people/charlie-example' AND source_id = 'default'`,
    [],
  );
  if (charliePage.length > 0) {
    for (let i = 0; i < 20; i++) {
      await engine.executeRaw(
        `INSERT INTO content_chunks (page_id, chunk_index, chunk_text)
         VALUES ($1, $2, $3)`,
        [charliePage[0].id, i, `Chunk ${i} about Charlie Example`],
      );
    }
  }

  // Give bob-example more connections than bob-rosenstein (15 vs 0)
  const bobPage = await engine.executeRaw<{ id: string }>(
    `SELECT id FROM pages WHERE slug = 'people/bob-example' AND source_id = 'default'`,
    [],
  );
  if (bobPage.length > 0) {
    for (let i = 0; i < 15; i++) {
      await engine.executeRaw(
        `INSERT INTO content_chunks (page_id, chunk_index, chunk_text)
         VALUES ($1, $2, $3)`,
        [bobPage[0].id, i, `Chunk ${i} about Bob Example`],
      );
    }
  }
})

