                const childGraph = makeGraph({
                    fsmId: "pod-bay",
                    initialState: "sealed",
                    nodes: { sealed: { name: "sealed", edges: [] } },
                    children: {},
                });
                const graph = makeGraph({
                    initialState: "docked",
