afterEach(() => {
    while (bootedHosts.length) {
        const host = bootedHosts.pop()!;
        host.remove();
    }
    if (hadVersion)
        (window as any)[MUYA_VERSION_KEY] = originalVersion;
    else
        delete (window as any)[MUYA_VERSION_KEY];
})

