beforeEach(async () => {
    getRequestCount = 0;
    unauthorizedPostCount = 0;
    requireAuth = false;
    let sessionId: string | undefined;

    httpServer = createServer(async (req, res) => {
      if (req.method === 'GET') {
        getRequestCount++;
        res.writeHead(200, {
          'content-type': 'text/event-stream',
          'cache-control': 'no-cache',
          connection: 'keep-alive',
        });
        // Close the SSE body immediately. This triggers _handleSseStream's
        // "done: true" branch which calls _scheduleReconnection({}, 0).
        res.end();
        return;
      }

      if (req.method === 'POST') {
        const chunks: Buffer[] = [];
        for await (const chunk of req) chunks.push(chunk as Buffer);
        const bodyText = Buffer.concat(chunks).toString('utf8');
        let body: any;
        try {
          body = JSON.parse(bodyText);
        } catch {
          res.writeHead(400).end();
          return;
        }

        // notifications/initialized => 202, no body, no auth needed
        if (body?.method === 'notifications/initialized') {
          res.writeHead(202).end();
          return;
        }

        // Auth check (gated by per-test flag): require Bearer token.
        if (requireAuth) {
          const authHeader = req.headers['authorization'];
          if (authHeader !== `Bearer ${VALID_TOKEN}`) {
            unauthorizedPostCount++;
            res
              .writeHead(401, { 'content-type': 'application/json' })
              .end(
                JSON.stringify({
                  jsonrpc: '2.0',
                  id: body?.id ?? null,
                  error: { code: -32001, message: 'unauthorized' },
                }),
              );
            return;
          }
        }

        if (body?.method === 'initialize') {
          sessionId = randomUUID();
          res.writeHead(200, {
            'content-type': 'application/json',
            'mcp-session-id': sessionId,
          });
          res.end(
            JSON.stringify({
              jsonrpc: '2.0',
              id: body.id,
              result: {
                protocolVersion: body.params?.protocolVersion ?? '2024-11-05',
                capabilities: { tools: {} },
                serverInfo: { name: 'loop-repro-server', version: '0.0.1' },
              },
            }),
          );
          return;
        }

        if (body?.method === 'tools/list') {
          res.writeHead(200, { 'content-type': 'application/json' }).end(
            JSON.stringify({
              jsonrpc: '2.0',
              id: body.id,
              result: {
                tools: [
                  {
                    name: 'echo',
                    description: 'Echo a message back',
                    inputSchema: {
                      type: 'object',
                      properties: { message: { type: 'string' } },
                      required: ['message'],
                    },
                  },
                ],
              },
            }),
          );
          return;
        }

        if (body?.method === 'tools/call') {
          const message = body.params?.arguments?.message ?? '';
          res.writeHead(200, { 'content-type': 'application/json' }).end(
            JSON.stringify({
              jsonrpc: '2.0',
              id: body.id,
              result: { content: [{ type: 'text', text: `echo: ${message}` }] },
            }),
          );
          return;
        }

        // Default: 202 ack
        res.writeHead(202).end();
        return;
      }

      res.writeHead(405).end();
    });

    baseUrl = await new Promise<URL>(resolve => {
      httpServer.listen(0, '127.0.0.1', () => {
        const addr = httpServer.address() as AddressInfo;
        resolve(new URL(`http://127.0.0.1:${addr.port}/mcp`));
      });
    });
  })

