                new Promise<ReturnType<typeof makeClient>[]>(res => {
                    resolveMatchAll = res;
                })
            );

            ({ createServiceWorkerTransport } = await import("./serviceWorkerTransport"));
            transport = createServiceWorkerTransport();

            // send() fires, matchAll is pending
